#include <stdio.h>

int main(void) {
    int n, q;
    scanf("%d %d", &n, &q);

    int current[50][50] = {0};
    int next[50][50];

    for (int i = 0; i < n; i++) {
        char row[55];
        scanf("%s", row);
        for (int j = 0; j < n; j++) {
            current[i][j] = row[j] - '0';
        }
    }

    for (int step = 0; step < q; step++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int neighbors = 0;
                for (int di = -1; di <= 1; di++) {
                    for (int dj = -1; dj <= 1; dj++) {
                        if (di == 0 && dj == 0) continue;
                        int ni = i + di;
                        int nj = j + dj;
                        if (ni >= 0 && ni < n && nj >= 0 && nj < n) {
                            neighbors += current[ni][nj];
                        }
                    }
                }

                next[i][j] = current[i][j]
                    ? (neighbors == 2 || neighbors == 3)
                    : (neighbors == 3);
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                current[i][j] = next[i][j];
            }
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            putchar(current[i][j] ? '1' : '0');
        }
        putchar('\n');
    }

    return 0;
}
